#include <stdio.h>
#include <ctype.h>

int main(void) {
    long long total = 0;
    int c;

    /* Skip leading whitespace. */
    do {
        c = getchar();
    } while (c != EOF && isspace((unsigned char)c));

    if (c == EOF) {
        printf("0\n");
        return 0;
    }

    /* Parse the first signed integer. */
    int sign = 1;
    if (c == '-') {
        sign = -1;
        c = getchar();
    } else if (c == '+') {
        c = getchar();
    }
    while (c != EOF && isspace((unsigned char)c)) {
        c = getchar();
    }

    long long number = 0;
    while (c != EOF && isdigit((unsigned char)c)) {
        number = number * 10 + (c - '0');
        c = getchar();
    }
    total = sign * number;

    /* Parse remaining + and - terms. */
    while (c != EOF) {
        if (isspace((unsigned char)c)) {
            c = getchar();
            continue;
        }

        if (c != '+' && c != '-') {
            c = getchar();
            continue;
        }

        int op = c;
        c = getchar();

        while (c != EOF && isspace((unsigned char)c)) {
            c = getchar();
        }

        int term_sign = 1;
        if (c == '-') {
            term_sign = -1;
            c = getchar();
        } else if (c == '+') {
            c = getchar();
        }

        while (c != EOF && isspace((unsigned char)c)) {
            c = getchar();
        }

        long long term = 0;
        while (c != EOF && isdigit((unsigned char)c)) {
            term = term * 10 + (c - '0');
            c = getchar();
        }
        term *= term_sign;

        if (op == '+') {
            total += term;
        } else {
            total -= term;
        }
    }

    printf("%lld\n", total);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static int compare_words(const void *a, const void *b)
{
    const char *const *pa = a;
    const char *const *pb = b;
    return strcmp(*pa, *pb);
}

int main(void)
{
    size_t capacity = 0;
    size_t length = 0;
    char *input = NULL;
    int c;

    while ((c = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity ? capacity * 2 : 128;
            char *tmp = realloc(input, new_capacity);
            if (tmp == NULL) {
                free(input);
                return 1;
            }
            input = tmp;
            capacity = new_capacity;
        }
        input[length++] = (char)c;
    }

    if (input == NULL) {
        input = malloc(1);
        if (input == NULL) {
            return 1;
        }
        input[0] = '\0';
    } else {
        input[length] = '\0';
    }

    size_t word_capacity = 0;
    size_t word_count = 0;
    char **words = NULL;
    int in_word = 0;

    for (char *p = input; *p != '\0'; ++p) {
        if (isspace((unsigned char)*p)) {
            *p = '\0';
            in_word = 0;
        } else {
            if (!in_word) {
                if (word_count == word_capacity) {
                    size_t new_word_capacity = word_capacity ? word_capacity * 2 : 16;
                    char **tmp = realloc(words, new_word_capacity * sizeof *words);
                    if (tmp == NULL) {
                        free(words);
                        free(input);
                        return 1;
                    }
                    words = tmp;
                    word_capacity = new_word_capacity;
                }
                words[word_count++] = p;
                in_word = 1;
            }
        }
    }

    qsort(words, word_count, sizeof *words, compare_words);

    for (size_t i = 0; i < word_count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    putchar('\n');

    free(words);
    free(input);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int roman_value(char c) {
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default: return 0;
    }
}

int main(void) {
    size_t cap = 64, len = 0;
    char *s = malloc(cap);
    if (s == NULL) {
        return 1;
    }

    int ch;
    while ((ch = getchar()) != EOF) {
        if (isspace((unsigned char)ch)) {
            continue;
        }
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(s, cap);
            if (tmp == NULL) {
                free(s);
                return 1;
            }
            s = tmp;
        }
        s[len++] = (char)ch;
    }
    s[len] = '\0';

    long total = 0;
    for (size_t i = 0; i < len; i++) {
        char c = (char)toupper((unsigned char)s[i]);
        int value = roman_value(c);
        int next = 0;
        if (i + 1 < len) {
            next = roman_value((char)toupper((unsigned char)s[i + 1]));
        }
        if (value < next) {
            total -= value;
        } else {
            total += value;
        }
    }

    printf("%ld\n", total);
    free(s);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 1 || n > 3999) {
        return 0;
    }

    static const char * const thousands[] = {"", "M", "MM", "MMM"};
    static const char * const hundreds[]  = {"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"};
    static const char * const tens[]      = {"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"};
    static const char * const ones[]      = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"};

    printf("%s%s%s%s\n",
           thousands[n / 1000],
           hundreds[(n / 100) % 10],
           tens[(n / 10) % 10],
           ones[n % 10]);

    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            printf("%d", i * j);
            if (j < n) printf(" ");
        }
