static long long phi(long long n)
{
    if (n <= 0)
        return 0;

    unsigned long long m = (unsigned long long)n;
    unsigned long long result = m;

    if (m % 2 == 0) {
        result -= result / 2;
        while (m % 2 == 0)
            m /= 2;
    }

    for (unsigned long long p = 3; p * p <= m; p += 2) {
        if (m % p == 0) {
            result -= result / p;
            while (m % p == 0)
                m /= p;
        }
    }

    if (m > 1)
        result -= result / m;

    return (long long)result;
}

