#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return 1;
    }

    int has_newline = 0;
    int c;
    while ((c = getchar()) != EOF) {
        if (c == '\n') {
            has_newline = 1;
            break;
        }
        if (len + 1 > cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                free(buf);
                return 1;
            }
            buf = tmp;
        }
        buf[len++] = (char)c;
    }

    for (size_t i = 0, j = len; i < j; ) {
        --j;
        char t = buf[i];
        buf[i] = buf[j];
        buf[j] = t;
        ++i;
    }

    if (fwrite(buf, 1, len, stdout) != len) {
        free(buf);
        return 1;
    }
    if (has_newline && fputc('\n', stdout) == EOF) {
        free(buf);
        return 1;
    }

    free(buf);
    return 0;
}

