static char *read_line(void) {
    size_t capacity = 128;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        if (length + 1 >= capacity) {
            if (capacity > SIZE_MAX / 2) {
                free(buffer);
                return NULL;
            }
            capacity *= 2;

            char *new_buffer = realloc(buffer, capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
        }

        buffer[length++] = (char)c;
    }

    if (length == 0 && c == EOF) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void) {
    char *line = read_line();

    if (line == NULL) {
        if (ferror(stdin)) {
            perror("stdin");
            return EXIT_FAILURE;
        }
        return EXIT_SUCCESS;
    }

    const char *best = NULL;
    size_t best_len = 0;
    const char *p = line;

    while (*p != '\0') {
        while (*p != '\0' && isspace((unsigned char)*p)) {
            ++p;
        }
        if (*p == '\0') {
            break;
        }

        const char *start = p;
        while (*p != '\0' && !isspace((unsigned char)*p)) {
            ++p;
        }

        size_t len = (size_t)(p - start);
        if (len > best_len) {
            best = start;
            best_len = len;
        }
    }

    if (best != NULL) {
        if (fwrite(best, 1, best_len, stdout) != best_len ||
            putchar('\n') == EOF) {
            free(line);
            return EXIT_FAILURE;
        }
    }

    free(line);
    return EXIT_SUCCESS;
}

