    char *s = buf;
    while (isspace((unsigned char)*s)) {
        s++;
    }
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) {
        *--end = '\0';
    }

    if (*s == '\0') {
        puts("0");
        goto cleanup;
    }

    for (char *q = s; *q != '\0'; q++) {
        if (!isxdigit((unsigned char)*q)) {
            fprintf(stderr, "error: invalid hexadecimal input\n");
            status = 1;
            goto cleanup;
        }
    }

    const char *p = s;
    while (*p == '0') {
        p++;
    }
    if (*p == '\0') {
        puts("0");
        goto cleanup;
    }

    size_t hexlen = strlen(p);
    size_t padded_len = hexlen + (hexlen & 1U);

    hex = malloc(padded_len + 1);
    if (hex == NULL) {
        fprintf(stderr, "error: out of memory\n");
        status = 1;
        goto cleanup;
    }

    if (hexlen & 1U) {
        hex[0] = '0';
        memcpy(hex + 1, p, hexlen + 1);
    } else {
        memcpy(hex, p, hexlen + 1);
    }

    size_t nbytes = padded_len / 2;
    size_t nwords = (nbytes + 3) / 4;
    if (nwords == 0) {
        nwords = 1;
    }

    words = calloc(nwords, sizeof *words);
    if (words == NULL) {
        fprintf(stderr, "error: out of memory\n");
        status = 1;
        goto cleanup;
    }

    for (size_t i = 0; i < nbytes; i++) {
        int hi = hex_value(hex[2 * i]);
        int lo = hex_value(hex[2 * i + 1]);
        unsigned char byte = (unsigned char)((hi << 4) | lo);
        size_t byte_index = nbytes - 1 - i;
        words[byte_index / 4] |= (uint32_t)byte << (8 * (byte_index % 4));
    }

    while (nwords > 1 && words[nwords - 1] == 0) {
        nwords--;
    }

    size_t chunk_cap = 16;
    size_t chunk_n = 0;
    chunks = malloc(chunk_cap * sizeof *chunks);
    if (chunks == NULL) {
        fprintf(stderr, "error: out of memory\n");
        status = 1;
        goto cleanup;
    }

    while (!(nwords == 1 && words[0] == 0)) {
        if (chunk_n == chunk_cap) {
            chunk_cap *= 2;
            uint32_t *tmp = realloc(chunks, chunk_cap * sizeof *chunks);
            if (tmp == NULL) {
                fprintf(stderr, "error: out of memory\n");
                status = 1;
                goto cleanup;
            }
            chunks = tmp;
        }

        uint32_t rem = 0;
        for (size_t i = nwords; i-- > 0; ) {
            uint64_t cur = ((uint64_t)rem << 32) | words[i];
            words[i] = (uint32_t)(cur / 1000000000ULL);
            rem = (uint32_t)(cur % 1000000000ULL);
        }

        chunks[chunk_n++] = rem;

        while (nwords > 1 && words[nwords - 1] == 0) {
            nwords--;
        }
    }

    if (chunk_n == 0) {
        puts("0");
    } else {
        printf("%u", chunks[chunk_n - 1]);
        for (size_t i = chunk_n - 1; i-- > 0; ) {
            printf("%09u", chunks[i]);
        }
        putchar('\n');
    }

cleanup:
    free(chunks);
    free(words);
    free(hex);
    free(buf);
    return status;
}

