}

#include <stdio.h>
#include <stdlib.h>

static void sift_down(int *a, size_t n, size_t i)
{
    while (2 * i + 1 < n) {
        size_t child = 2 * i + 1;
        if (child + 1 < n && a[child + 1] > a[child]) {
            ++child;
        }
        if (a[i] >= a[child]) {
            break;
        }
        int tmp = a[i];
        a[i] = a[child];
        a[child] = tmp;
        i = child;
    }
}

static void heap_sort(int *a, size_t n)
{
    if (n < 2) {
        return;
    }

    for (size_t i = n / 2; i > 0; ) {
        --i;
        sift_down(a, n, i);
    }

    for (size_t end = n; end > 1; ) {
        --end;
        int tmp = a[0];
        a[0] = a[end];
        a[end] = tmp;
        sift_down(a, end, 0);
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 1;
    }

    size_t count = (size_t)n;
    int *values = count == 0 ? NULL : malloc(count * sizeof *values);
    if (count != 0 && values == NULL) {
        return 1;
    }

    for (size_t i = 0; i < count; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            free(values);
            return 1;
        }
    }

    heap_sort(values, count);

    for (size_t i = 0; i < count; ++i) {
        printf("%d%c", values[i], i + 1 < count ? ' ' : '\n');
    }
    if (count == 0) {
        putchar('\n');
    }

    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 1;
    }

    int *values = malloc((size_t)n * sizeof *values);
    if (n > 0 && values == NULL) {
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            free(values);
            return 1;
        }
    }

    int target;
    if (scanf("%d", &target) != 1) {
        free(values);
        return 1;
    }

    int left = 0;
    int right = n - 1;
    int index = -1;

    while (left <= right) {
        int middle = left + (right - left) / 2;

        if (values[middle] == target) {
            index = middle;
            break;
        }

        if (values[middle] < target) {
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }

    printf("%d\n", index);

    free(values);
    return 0;
}

#include <stdio.h>
