int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 2) {
        return 0;
    }

    long long max = LLONG_MIN;
    long long second = LLONG_MIN;

    for (int i = 0; i < n; ++i) {
        long long value;

        if (scanf("%lld", &value) != 1) {
            return 1;
        }

        if (value > max) {
            second = max;
            max = value;
        } else if (value > second) {
            second = value;
        }
    }

    printf("%lld %lld\n", max, second);
    return 0;
}

